import * as React from "react";
import { Slot } from "@radix-ui/react-slot";

import { cn } from "@/lib/utils";

/**
 * figma: Questionnaire — a stepped survey. One item is active at a time;
 * progress and navigation stay stationary while the item changes.
 *
 *   <Questionnaire value={answers} onValueChange={setAnswers}>
 *     <QuestionnaireHeader>
 *       <QuestionnaireTitle>How was it?</QuestionnaireTitle>
 *       <QuestionnaireDescription>Pick one.</QuestionnaireDescription>
 *     </QuestionnaireHeader>
 *     <QuestionnaireProgress />
 *     <QuestionnaireItem name="rating" multiple shortcuts>
 *       <QuestionnaireChoices>
 *         <QuestionnaireChoice value="good">Good</QuestionnaireChoice>
 *       </QuestionnaireChoices>
 *       <QuestionnaireInput placeholder="Something else…" />
 *       <QuestionnaireSkip>Skip</QuestionnaireSkip>
 *     </QuestionnaireItem>
 *     <QuestionnaireActions>…</QuestionnaireActions>
 *   </Questionnaire>
 *
 * Recipes: Multiple Selection · Freeform Answer · Explicit Skip · Shortcuts ·
 * Custom Validation · Controlled · Resume · Conditional Items ·
 * Navigation State · Custom Progress · Animated Items · Card · Dialog.
 */
type Answer = string | string[] | null;

type QuestionnaireContextValue = {
  activeItem: string | null;
  setActiveItem: (id: string) => void;
  items: string[];
  register: (id: string) => void;
  unregister: (id: string) => void;
  value: Record<string, Answer>;
  setAnswer: (name: string, answer: Answer) => void;
  index: number;
  total: number;
  next: () => void;
  previous: () => void;
  canGoNext: boolean;
  canGoPrevious: boolean;
};

const QuestionnaireContext = React.createContext<QuestionnaireContextValue | null>(null);

/** Read questionnaire state from anywhere inside it. */
function useQuestionnaire() {
  const ctx = React.useContext(QuestionnaireContext);
  if (!ctx) throw new Error("Questionnaire parts must be used within <Questionnaire>.");
  return ctx;
}

function Questionnaire({
  className,
  children,
  activeItem: activeItemProp,
  defaultActiveItem,
  onActiveItemChange,
  value: valueProp,
  defaultValue,
  onValueChange,
  ...props
}: Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> & {
  /** Control the active item from host state — e.g. to return to an invalid step. */
  activeItem?: string;
  defaultActiveItem?: string;
  onActiveItemChange?: (id: string) => void;
  value?: Record<string, Answer>;
  defaultValue?: Record<string, Answer>;
  onValueChange?: (value: Record<string, Answer>) => void;
}) {
  const [items, setItems] = React.useState<string[]>([]);
  const [uncontrolledActive, setUncontrolledActive] = React.useState<string | null>(
    defaultActiveItem ?? null
  );
  const activeItem = activeItemProp ?? uncontrolledActive ?? items[0] ?? null;

  const setActiveItem = React.useCallback(
    (id: string) => (onActiveItemChange ? onActiveItemChange(id) : setUncontrolledActive(id)),
    [onActiveItemChange]
  );

  const [uncontrolledValue, setUncontrolledValue] = React.useState<Record<string, Answer>>(
    defaultValue ?? {}
  );
  const value = valueProp ?? uncontrolledValue;
  const setAnswer = React.useCallback(
    (name: string, answer: Answer) => {
      const next = { ...value, [name]: answer };
      if (onValueChange) onValueChange(next);
      else setUncontrolledValue(next);
    },
    [value, onValueChange]
  );

  const register = React.useCallback(
    (id: string) => setItems((prev) => (prev.includes(id) ? prev : [...prev, id])),
    []
  );
  const unregister = React.useCallback(
    (id: string) => setItems((prev) => prev.filter((x) => x !== id)),
    []
  );

  const index = activeItem ? items.indexOf(activeItem) : -1;
  const total = items.length;
  const canGoNext = index > -1 && index < total - 1;
  const canGoPrevious = index > 0;
  const next = React.useCallback(() => {
    if (canGoNext) setActiveItem(items[index + 1]);
  }, [canGoNext, items, index, setActiveItem]);
  const previous = React.useCallback(() => {
    if (canGoPrevious) setActiveItem(items[index - 1]);
  }, [canGoPrevious, items, index, setActiveItem]);

  return (
    <QuestionnaireContext.Provider
      value={{
        activeItem, setActiveItem, items, register, unregister,
        value, setAnswer, index, total, next, previous, canGoNext, canGoPrevious,
      }}
    >
      <div data-slot="questionnaire" className={cn("flex flex-col gap-4", className)} {...props}>
        {children}
      </div>
    </QuestionnaireContext.Provider>
  );
}

function QuestionnaireHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="questionnaire-header"
      className={cn("flex flex-col gap-1", className)}
      {...props}
    />
  );
}

/** Keep the question title semantic even when composed into Card or Dialog slots. */
function QuestionnaireTitle({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"h3"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "h3";
  return (
    <Comp
      data-slot="questionnaire-title"
      className={cn("text-base leading-none font-semibold", className)}
      {...props}
    />
  );
}

function QuestionnaireDescription({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"p"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "p";
  return (
    <Comp
      data-slot="questionnaire-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

/**
 * The default progress bar. Pass `children` as a function to build your own
 * indicator from the render state.
 */
function QuestionnaireProgress({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  children?: (state: { index: number; total: number; percent: number }) => React.ReactNode;
}) {
  const { index, total } = useQuestionnaire();
  const percent = total ? ((index + 1) / total) * 100 : 0;
  if (children) {
    return (
      <div data-slot="questionnaire-progress" className={className} {...props}>
        {children({ index, total, percent })}
      </div>
    );
  }
  return (
    <div
      data-slot="questionnaire-progress"
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={total}
      aria-valuenow={index + 1}
      className={cn("h-1 w-full overflow-hidden rounded-full bg-muted", className)}
      {...props}
    >
      <div className="h-full bg-primary transition-all" style={{ width: `${percent}%` }} />
    </div>
  );
}

const ItemContext = React.createContext<{
  name: string;
  multiple: boolean;
  shortcuts: boolean;
  disabled: boolean;
  answer: Answer;
  toggle: (v: string) => void;
} | null>(null);

function useQuestionnaireItem() {
  const ctx = React.useContext(ItemContext);
  if (!ctx) throw new Error("Questionnaire choices must be used within <QuestionnaireItem>.");
  return ctx;
}

/** One question. `disabled` opts it out — use it for conditional items. */
function QuestionnaireItem({
  className,
  name,
  multiple = false,
  shortcuts = false,
  disabled = false,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  name: string;
  multiple?: boolean;
  shortcuts?: boolean;
  disabled?: boolean;
}) {
  const { register, unregister, activeItem, value, setAnswer } = useQuestionnaire();

  React.useEffect(() => {
    register(name);
    return () => unregister(name);
  }, [name, register, unregister]);

  const answer = value[name] ?? (multiple ? [] : null);

  const toggle = React.useCallback(
    (v: string) => {
      if (disabled) return;
      if (multiple) {
        const current = Array.isArray(answer) ? answer : [];
        setAnswer(name, current.includes(v) ? current.filter((x) => x !== v) : [...current, v]);
      } else {
        setAnswer(name, v);
      }
    },
    [disabled, multiple, answer, name, setAnswer]
  );

  const isActive = activeItem === name;

  return (
    <ItemContext.Provider value={{ name, multiple, shortcuts, disabled, answer, toggle }}>
      <div
        data-slot="questionnaire-item"
        data-active={isActive || undefined}
        data-disabled={disabled || undefined}
        hidden={!isActive}
        className={cn("flex flex-col gap-3 data-[disabled]:opacity-50", className)}
        {...props}
      >
        {children}
      </div>
    </ItemContext.Provider>
  );
}

function QuestionnaireChoices({ className, ...props }: React.ComponentProps<"div">) {
  const { multiple } = useQuestionnaireItem();
  return (
    <div
      role={multiple ? "group" : "radiogroup"}
      data-slot="questionnaire-choices"
      className={cn("flex flex-col gap-2", className)}
      {...props}
    />
  );
}

/**
 * A selectable row. `shortcut` assigns a letter or number key to the answer;
 * it is shown when the item has `shortcuts`.
 */
function QuestionnaireChoice({
  className,
  value,
  shortcut,
  children,
  ...props
}: Omit<React.ComponentProps<"button">, "value"> & { value: string; shortcut?: string }) {
  const { multiple, shortcuts, disabled, answer, toggle } = useQuestionnaireItem();
  const checked = Array.isArray(answer) ? answer.includes(value) : answer === value;

  React.useEffect(() => {
    if (!shortcuts || !shortcut || disabled) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key.toLowerCase() === shortcut.toLowerCase() && !e.metaKey && !e.ctrlKey) {
        const el = document.activeElement;
        if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) return;
        e.preventDefault();
        toggle(value);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shortcuts, shortcut, disabled, toggle, value]);

  return (
    <button
      type="button"
      role={multiple ? "checkbox" : "radio"}
      aria-checked={checked}
      disabled={disabled}
      data-slot="questionnaire-choice"
      data-state={checked ? "checked" : "unchecked"}
      onClick={() => toggle(value)}
      className={cn(
        "flex cursor-pointer items-center gap-2.5 rounded-lg border border-border bg-transparent",
        "px-3 py-2.5 text-start text-sm font-medium transition-colors",
        "hover:bg-muted/50",
        "data-[state=checked]:border-primary/40 data-[state=checked]:bg-muted",
        "focus-visible:border-ring focus-visible:ring-ring-subtle focus-visible:ring-[3px] focus-visible:outline-none",
        "disabled:pointer-events-none disabled:opacity-50",
        className
      )}
      {...props}
    >
      <QuestionnaireChoiceIndicator checked={checked} multiple={multiple} />
      <QuestionnaireChoiceLabel>{children}</QuestionnaireChoiceLabel>
      {shortcuts && shortcut ? (
        <kbd
          data-slot="questionnaire-choice-shortcut"
          className="ms-auto inline-flex h-5 min-w-5 items-center justify-center rounded-sm bg-muted px-1 text-xs text-muted-foreground"
        >
          {shortcut}
        </kbd>
      ) : null}
    </button>
  );
}

function QuestionnaireChoiceIndicator({
  className,
  checked,
  multiple,
  ...props
}: React.ComponentProps<"span"> & { checked?: boolean; multiple?: boolean }) {
  return (
    <span
      data-slot="questionnaire-choice-indicator"
      aria-hidden
      className={cn(
        "flex size-4 shrink-0 items-center justify-center border border-input bg-background",
        multiple ? "rounded-xs" : "rounded-full",
        checked && "border-primary bg-primary",
        className
      )}
      {...props}
    >
      {checked ? (
        <span
          data-slot="questionnaire-choice-indicator-dot"
          className={cn(
            "bg-primary-foreground",
            multiple ? "size-2 rounded-[1px]" : "size-1.5 rounded-full"
          )}
        />
      ) : null}
    </span>
  );
}

function QuestionnaireChoiceLabel({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span data-slot="questionnaire-choice-label" className={cn("min-w-0", className)} {...props} />
  );
}

/** A freeform answer, composed alongside fixed choices. */
function QuestionnaireInput({ className, ...props }: React.ComponentProps<"input">) {
  const { name, disabled } = useQuestionnaireItem();
  const { setAnswer } = useQuestionnaire();
  return (
    <input
      data-slot="questionnaire-input"
      disabled={disabled}
      onChange={(e) => setAnswer(name, e.target.value)}
      className={cn(
        "h-8 w-full rounded-lg border border-input bg-background px-2.5 text-sm shadow-xs outline-none",
        "placeholder:text-muted-foreground",
        "focus-visible:border-ring focus-visible:ring-ring-subtle focus-visible:ring-[3px]",
        "disabled:pointer-events-none disabled:bg-input/50",
        className
      )}
      {...props}
    />
  );
}

/** Marks an optional item as intentionally unanswered. */
function QuestionnaireSkip({
  className,
  children = "Skip",
  onClick,
  ...props
}: React.ComponentProps<"button">) {
  const { name } = useQuestionnaireItem();
  const { setAnswer, next } = useQuestionnaire();
  return (
    <button
      type="button"
      data-slot="questionnaire-skip"
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        setAnswer(name, null);
        next();
      }}
      className={cn(
        "w-fit text-sm text-muted-foreground underline-offset-4 hover:underline",
        "focus-visible:ring-ring-subtle focus-visible:ring-[3px] focus-visible:outline-none",
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
}

function QuestionnaireActions({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="questionnaire-actions"
      className={cn("flex items-center justify-between gap-2", className)}
      {...props}
    />
  );
}

export {
  Questionnaire,
  QuestionnaireHeader,
  QuestionnaireTitle,
  QuestionnaireDescription,
  QuestionnaireProgress,
  QuestionnaireItem,
  QuestionnaireChoices,
  QuestionnaireChoice,
  QuestionnaireChoiceIndicator,
  QuestionnaireChoiceLabel,
  QuestionnaireInput,
  QuestionnaireSkip,
  QuestionnaireActions,
  useQuestionnaire,
};
